-- PCI DSS v4.0.1 (framework pci-dss-4.0). Requirement level for the sections a
-- scan can speak to — 2.2 secure configuration, 6.2–6.4 secure development and
-- vulnerability management, 8.3/8.6 authentication and credentials, 11.3
-- vulnerability scanning — and section level (x.y) elsewhere. A control is
-- measured when a signal maps to it: CWE classes, leaked secrets, open
-- critical/high findings (11.3.1), KEV / SLA / SBOM, curated Checkov and Trivy
-- checks, and the Prowler checks Prowler's PCI 4.0 packs map (requirement 12 and
-- the appendices stay attested). Everything else is manual.
-- Titles are paraphrased, never the standard's text.

INSERT INTO frameworks (key, name, version, description)
VALUES ('pci-dss-4.0', 'PCI DSS', '4.0.1',
        'Payment Card Industry Data Security Standard v4.0.1. Requirements a scan can evidence (secure configuration 2.2, secure development 6.2–6.4, authentication 8.3/8.6, vulnerability scanning 11.3, and the cloud checks Prowler maps) are measured; the rest are attested. Titles are paraphrased; consult the standard for the requirement text.');

