-- By finding category.
INSERT INTO control_mappings (control_id, match_type, category)
SELECT c.id, 'category', v.category
FROM controls c
JOIN frameworks fw ON fw.id = c.framework_id AND fw.key = 'pci-dss-4.0'
JOIN (VALUES
    ('8.6.2', 'secret')
) AS v(code, category) ON v.code = c.code;

-- By finding severity.
INSERT INTO control_mappings (control_id, match_type, severity)
SELECT c.id, 'severity', v.severity
FROM controls c
JOIN frameworks fw ON fw.id = c.framework_id AND fw.key = 'pci-dss-4.0'
JOIN (VALUES
    ('11.3.1', 'critical'), ('11.3.1', 'high')
) AS v(code, severity) ON v.code = c.code;

-- By finding state (kev, sla) or project fact (sbom, vex).
INSERT INTO control_mappings (control_id, match_type)
SELECT c.id, v.match_type
FROM controls c
JOIN frameworks fw ON fw.id = c.framework_id AND fw.key = 'pci-dss-4.0'
JOIN (VALUES
    ('6.3.2', 'sbom'),
    ('6.3.3', 'kev'), ('6.3.3', 'sla'),
    ('11.3.1.1', 'sla')
) AS v(code, match_type) ON v.code = c.code;
